  <script>
    // --- Clock ---
    function updateClock() {
      const now = new Date();
      const opts = { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit', hour12: false };
      const clockEl = document.getElementById('top-clock');
      if (clockEl) {
        clockEl.textContent = now.toLocaleDateString(undefined, opts);
      }
    }
    updateClock();
    setInterval(updateClock, 1000);

    // --- Window Dragging & Depth Management ---
    let topZIndex = 10;
    function bringToFront(winEl) {
      topZIndex++;
      winEl.style.zIndex = topZIndex;
    }

    function makeDraggable(winEl) {
      const header = winEl.querySelector('.win-header');
      let isDragging = false;
      let startX, startY, initLeft, initTop;

      header.addEventListener('mousedown', (e) => {
        if (e.target.closest('.win-btn')) return;
        isDragging = true;
        bringToFront(winEl);
        startX = e.clientX;
        startY = e.clientY;
        const rect = winEl.getBoundingClientRect();
        initLeft = rect.left;
        initTop = rect.top;
        e.preventDefault();
      });

      document.addEventListener('mousemove', (e) => {
        if (!isDragging) return;
        const dx = e.clientX - startX;
        const dy = e.clientY - startY;
        const newLeft = Math.max(0, Math.min(window.innerWidth - 60, initLeft + dx));
        const newTop = Math.max(28, Math.min(window.innerHeight - 40, initTop + dy));
        winEl.style.left = newLeft + 'px';
        winEl.style.top = newTop + 'px';
      });

      document.addEventListener('mouseup', () => {
        isDragging = false;
      });

      winEl.addEventListener('mousedown', () => {
        bringToFront(winEl);
      });
    }

    const filesWin = document.getElementById('files-window');
    const notepadWin = document.getElementById('notepad-window');
    makeDraggable(filesWin);
    makeDraggable(notepadWin);

    // --- Dock / Taskbar Launchers & Window Controls ---
    const openFilesBtn = document.getElementById('open-files');
    const openNotepadBtn = document.getElementById('open-notepad');

    function syncDockState() {
      openFilesBtn.classList.toggle('is-open', filesWin.style.display !== 'none');
      openNotepadBtn.classList.toggle('is-open', notepadWin.style.display !== 'none');
    }

    openFilesBtn.addEventListener('click', () => {
      filesWin.style.display = 'flex';
      bringToFront(filesWin);
      syncDockState();
    });

    openNotepadBtn.addEventListener('click', () => {
      notepadWin.style.display = 'flex';
      bringToFront(notepadWin);
      renderTabs();
      syncDockState();
      document.getElementById('editor').focus();
    });

    filesWin.querySelector('.win-close').addEventListener('click', () => {
      filesWin.style.display = 'none';
      syncDockState();
    });

    notepadWin.querySelector('.win-close').addEventListener('click', () => {
      saveActiveTabContent();
      notepadWin.style.display = 'none';
      syncDockState();
    });

    // --- Files App Data & Logic ---
    const fsData = {
      bin: {
        type: 'folder',
        children: {
          bash: { type: 'file' },
          cat: { type: 'file' },
          cp: { type: 'file' },
          ls: { type: 'file' },
          mkdir: { type: 'file' },
          sh: { type: 'file' }
        }
      },
      etc: {
        type: 'folder',
        children: {
          hostname: { type: 'file' },
          hosts: { type: 'file' },
          passwd: { type: 'file' },
          fstab: { type: 'file' }
        }
      },
      home: {
        type: 'folder',
        children: {
          user: {
            type: 'folder',
            children: {
              Documents: {
                type: 'folder',
                children: {
                  'notes.txt': { type: 'file' },
                  'project.md': { type: 'file' }
                }
              },
              Downloads: {
                type: 'folder',
                children: {
                  'ubuntu-24.04-desktop.iso': { type: 'file' },
                  'setup.sh': { type: 'file' }
                }
              },
              Pictures: {
                type: 'folder',
                children: {
                  'wallpaper.png': { type: 'file' },
                  'screenshot.png': { type: 'file' }
                }
              },
              'welcome.txt': { type: 'file' }
            }
          }
        }
      },
      usr: {
        type: 'folder',
        children: {
          bin: { type: 'folder', children: {} },
          lib: { type: 'folder', children: {} },
          share: { type: 'folder', children: {} }
        }
      },
      var: {
        type: 'folder',
        children: {
          log: { type: 'folder', children: {} },
          tmp: { type: 'folder', children: {} }
        }
      }
    };

    let currentPath = '/';
    const filesPathEl = document.getElementById('files-path');
    const filesListEl = document.getElementById('files-list');
    const filesUpBtn = document.getElementById('files-up');

    function resolveNode(path) {
      if (path === '/' || !path) return { type: 'folder', children: fsData };
      const parts = path.split('/').filter(Boolean);
      let curr = { type: 'folder', children: fsData };
      for (const p of parts) {
        if (!curr.children || !curr.children[p]) return null;
        curr = curr.children[p];
      }
      return curr;
    }

    function renderFiles() {
      filesPathEl.textContent = currentPath;
      filesListEl.innerHTML = '';

      const node = resolveNode(currentPath);
      if (!node || node.type !== 'folder') return;

      const entries = Object.entries(node.children || {}).sort(([nameA, a], [nameB, b]) => {
        if (a.type !== b.type) return a.type === 'folder' ? -1 : 1;
        return nameA.localeCompare(nameB);
      });

      entries.forEach(([name, entry]) => {
        const itemEl = document.createElement('div');
        itemEl.className = 'fs-item ' + (entry.type === 'folder' ? 'is-folder' : 'is-file');
