      const nextActive = notepadData.tabs[Math.max(0, idx - 1)];
      notepadData.activeId = nextActive ? nextActive.id : null;
    }
    saveNotepad();
    renderTabs();
  }

  editorEl.addEventListener('input', () => {
    const activeTab = notepadData.tabs.find(t => t.id === notepadData.activeId);
    if (activeTab) {
      activeTab.content = editorEl.value;
      saveNotepad();
    }
  });

  newTabBtn.addEventListener('click', createNewTab);

  loadNotepad();
  renderTabs();
</script>
